{"skill": "async (b) => {
  const find = (obs, name) => {
    const re = new RegExp('^- ' + name + ' \\([^)]*\\) at \\((\\d+),(\\d+)\\)', 'm');
    const m = obs.match(re);
    return m ? {x: +m[1], y: +m[2]} : null;
  };
  const inv = async () => {
    const items = await b.items();
    const map = {};
    for (const it of items) map[it.name] = (map[it.name] || 0) + it.stack;
    return map;
  };
  const pick = async (name) => {
    for (let i = 0; i < 12; i++) {
      const obs = await b.observe();
      const p = find(obs, name);
      if (!p) return true;
      const r = await b.walkTo(p.x, p.y, 'adjacent');
      if (!r.ok) return false;
      await b.faceAndPress(p.x, p.y, 'KeyE');
      await b.wait(250);
      const after = await b.observe();
      if (!find(after, name)) return true;
    }
    return false;
  };
  const need = async (name, n) => {
    let have = (await inv())[name] || 0;
    while (have < n) {
      if (!(await pick(name))) return false;
      const nh = (await inv())[name] || 0;
      if (nh <= have) return false;
      have = nh;
    }
    return true;
  };
  if (!(await need('Wood', 3))) return false;
  if (!(await need('Stone', 2))) return false;
  const obs = await b.observe();
  const bench = find(obs, 'Workbench');
  if (!bench) return false;
  const r = await b.walkTo(bench.x, bench.y, 'adjacent');
  if (!r.ok) return false;
  await b.faceAndPress(bench.x, bench.y, 'KeyC');
  await b.wait(400);
  const items = await b.items();
  return items.some(i => /Crown/i.test(i.name));
}", "check": "async (b) => {
  const items = await b.items();
  const hasCrown = items.some(i => /Crown/i.test(i.name));
  return {ok: hasCrown, detail: hasCrown ? 'Crown crafted' : 'No crown in inventory'};
}"}
